# Check the balanced frequency hypothesis

def get_freq(shape_grid):
    counts = {}
    for row in shape_grid:
        for cell in row:
            if cell != 0:
                counts[cell] = counts.get(cell, 0) + 1
    return counts

def is_balanced(freq):
    """All non-zero cells appear with same count"""
    if not freq:
        return False
    values = list(freq.values())
    return all(v == values[0] for v in values)

demo_outputs = [
    ("Demo 1", [[1,3,3],[1,2,2],[1,3,2]]),
    ("Demo 2", [[5,5,5],[6,8,8],[6,5,5]]),
    ("Demo 3", [[1,6,2],[6,1,1],[2,6,1]])
]

print("Checking balanced frequency on demo outputs:")
for name, shape_grid in demo_outputs:
    freq = get_freq(shape_grid)
    print(f"{name}: {freq}, balanced={is_balanced(freq)}")

